  const begin=()=>active??={start:left+i,end:left+i,lines:[]};
  const flush=()=>{if(active){rows.push(active);active=null;}};
  while(i<n||j<m){
    if(i<n&&j<m&&aa[i]===bb[j]){flush();i++;j++;}
    else if(j<m&&(i===n||dp[i*width+j+1]>=dp[(i+1)*width+j])){begin().lines.push(bb[j++]);}
